<template><section class="page-content pos-page"><div class="page-heading"><div><p class="eyebrow">TRANSAKSI PENJUALAN</p><h1>POS</h1><p class="page-description">Catat penjualan, kelola pembayaran, dan kurangi stok saat transaksi dikunci.</p></div><button class="button button-primary" type="button" @click="router.push('/pos/baru')">+ Transaksi Baru</button></div><section class="panel"><div class="panel-header"><div><h2>Daftar Penjualan</h2><p>{{ transactions.length }} transaksi tercatat</p></div></div><div class="table-wrap"><table><thead><tr><th>Nomor</th><th>Tanggal</th><th>Pelanggan</th><th>Pembayaran</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="tx in transactions" :key="tx.id"><td>{{ tx.nomor }}</td><td>{{ formatDate(tx.tanggal) }}</td><td>{{ tx.pelangganNama || 'Umum' }}</td><td>{{ tx.metodePembayaran.toUpperCase() }}</td><td>{{ formatRupiah(tx.total) }}</td><td><span :class="['status-badge', tx.status === 'locked' ? 'status-locked' : 'status-draft']">{{ tx.status === 'locked' ? 'Terkunci' : 'Draft' }}</span></td><td><div class="row-actions"><button v-if="tx.status !== 'locked'" class="action-button edit-action" type="button" @click="router.push(`/pos/${tx.id}/edit`)">Edit</button><button v-if="tx.status !== 'locked'" class="action-button lock-action" type="button" @click="lockTransaction(tx)">Kunci</button><button class="action-button view-action" type="button" @click="detailOrder = tx">Detail</button></div></td></tr><tr v-if="!transactions.length"><td colspan="7" class="empty-cell">Belum ada transaksi penjualan.</td></tr></tbody></table></div></section><div v-if="detailOrder" class="modal-backdrop receipt-backdrop" @click.self="detailOrder = null"><section class="receipt-modal"><header class="receipt-modal-header"><div><p class="eyebrow">DETAIL TRANSAKSI</p><h2>{{ detailOrder.nomor }}</h2><p>{{ formatDate(detailOrder.tanggal) }} · {{ detailOrder.status === 'locked' ? 'Terkunci' : 'Draft' }}</p></div><div class="receipt-header-actions"><button class="button button-secondary" type="button" @click="printReceipt">Cetak</button><button class="modal-close" type="button" @click="detailOrder = null">×</button></div></header><div class="receipt-paper" id="sale-receipt"><div class="receipt-brand"><strong>WARUNG SEMBAKO</strong><span>Struk Penjualan</span></div><div class="receipt-meta"><div><span>Nomor Transaksi</span><strong>{{ detailOrder.nomor }}</strong></div><div><span>Tanggal</span><strong>{{ formatDate(detailOrder.tanggal) }}</strong></div><div><span>Pelanggan</span><strong>{{ detailOrder.pelangganNama || 'Umum' }}</strong></div><div><span>Pembayaran</span><strong>{{ String(detailOrder.metodePembayaran || '').toUpperCase() }}</strong></div></div><div class="receipt-divider"></div><div class="receipt-items"><div v-for="item in detailOrder.items || []" :key="item.produkId" class="receipt-item"><div><strong>{{ item.nama }}</strong><small>{{ item.jumlah }} unit × {{ formatRupiah(item.hargaJual) }}</small></div><strong>{{ formatRupiah(item.jumlah * item.hargaJual) }}</strong></div></div><div class="receipt-divider"></div><div class="receipt-total"><span>Total Penjualan</span><strong>{{ formatRupiah(detailOrder.total) }}</strong></div><div :class="['receipt-status', detailOrder.metodePembayaran === 'utang' ? 'receipt-status-debt' : '']">{{ detailOrder.status === 'locked' ? 'TRANSAKSI TERKUNCI' : 'DRAFT TRANSAKSI' }}</div><p v-if="detailOrder.catatan" class="receipt-note">Catatan: {{ detailOrder.catatan }}</p><p class="receipt-thanks">Terima kasih telah berbelanja</p></div></section></div></section></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import { collection, doc, getDocs, runTransaction } from 'firebase/firestore'; import Swal from 'sweetalert2'; import { useRouter } from 'vue-router'; import { db } from '@/firebase'; import { authState } from '@/auth'; const router = useRouter(); const transactions = ref<any[]>([]); const detailOrder = ref<any | null>(null); const printReceipt = () => window.print(); const basePath = () => `warungs/${authState.warungId}`; const formatRupiah = (value: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value || 0); const formatDate = (value: string) => value ? new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium' }).format(new Date(value)) : '-'; const load = async () => { if (!authState.warungId) return; const snapshot = await getDocs(collection(db, basePath(), 'sales')); transactions.value = snapshot.docs.map((item) => ({ id: item.id, ...item.data() })) }; const lockTransaction = async (sale: any) => { const confirm = await Swal.fire({ title: 'Kunci transaksi?', text: 'Setelah dikunci, transaksi tidak dapat diedit dan stok akan berkurang.', icon: 'warning', showCancelButton: true, confirmButtonText: 'Ya, kunci transaksi', cancelButtonText: 'Batal', confirmButtonColor: '#2563eb' }); if (!confirm.isConfirmed || !authState.warungId) return; try { await runTransaction(db, async (transaction) => { const saleRef = doc(db, basePath(), 'sales', sale.id); const productRefs = (sale.items || []).map((item: any) => ({ item, ref: doc(db, basePath(), 'produk', item.produkId) })); const [saleSnapshot, ...productSnapshots] = await Promise.all([transaction.get(saleRef), ...productRefs.map(({ ref }: any) => transaction.get(ref))]); if (!saleSnapshot.exists() || saleSnapshot.data()?.status === 'locked') return; const lockedAt = new Date().toISOString(); productSnapshots.forEach((snapshot: any, index: number) => { const item = productRefs[index].item; const stock = Number(snapshot.data()?.stokPcs) || 0; const deduction = Number(item.jumlah) || 0; if (stock < deduction) throw new Error(`${item.nama || 'Produk'} tidak memiliki stok yang cukup.`); transaction.update(productRefs[index].ref, { stokPcs: stock - deduction, updatedAt: lockedAt }) }); transaction.update(saleRef, { status: 'locked', lockedAt }) }); await load(); await Swal.fire({ title: 'Transaksi dikunci', text: 'Stok produk berhasil diperbarui.', icon: 'success', confirmButtonColor: '#2563eb' }) } catch (error: any) { await Swal.fire({ title: 'Gagal mengunci transaksi', text: error?.message || 'Coba lagi.', icon: 'error', confirmButtonColor: '#2563eb' }) } }; onMounted(load);
</script>
